discrete BatteryStateMonitoringSystem
port:
    event input real BatteryConnected;
    event input real NormalSignalDetected;
    event input real AbnormalBatteryDetected;
    event input real AbnormalityResolved;
    event input real BatteryDisconnected;
state:
    initial state state1
        when entry() then
            statehold(0);
        end;
        when receive(BatteryConnected) then
            transition(state2);
        end;
        when receive(NormalSignalDetected) then
            transition(state2);
        end;
    end;

    state state2
        when entry() then
            statehold(0);
        end;
        when receive(AbnormalBatteryDetected) then
            transition(state3);
        end;
        when receive(BatteryDisconnected) then
            transition(state1);
        end;
    end;

    state state3
        when entry() then
            statehold(0);
        end;
        when receive(AbnormalityResolved) then
            transition(state2);
        end;
    end;
end;
end;

