couple BatteryManagementSystem
import architectureModels.BatteryStateMonitoringSystem as BSM;
import architectureModels.ChargeDischargeControlSystem as CDC;
import architectureModels.SafetyProtectionSystem as SPS;
import architectureModels.DataRecordingAndCommunicationSystem as DRC;
part:
    BSM bsm;
    CDC cdc;
    SPS sps;
    DRC drc;
connection:
    connect(bsm.BatteryStatus, cdc.BatteryStatus);
    connect(cdc.BatteryStatus, sps.BatteryStatus);
    connect(sps.BatteryStatus, drc.BatteryStatus);
    connect(bsm.NormalSignal, cdc.NormalSignal);
    connect(bsm.NormalSignal, sps.NormalSignal);
    connect(bsm.NormalSignal, drc.NormalSignal);
    connect(bsm.DisconnectSignal, cdc.DisconnectSignal);
    connect(cdc.DisconnectSignal, sps.DisconnectSignal);
    connect(sps.DisconnectSignal, drc.DisconnectSignal);
end;
